278	+  /// spec-6-1 — streaming companion to [post]: sent with
279	+  /// `ResponseType.stream` so the SSE response body never gets buffered
280	+  /// into a single in-memory JSON blob the way [post]'s own
281	+  /// `Dio.post<Map<String, dynamic>>` would. Each emitted `Right` is one
282	+  /// raw, UTF-8-decoded chunk straight off the wire — SSE `event:`/`data:`
283	+  /// line-splitting stays feature-local (`ChatRemoteDataSource`), this
284	+  /// façade only owns the transport + error-mapping step (Boundaries:
285	+  /// "ApiClient stays the one façade every datasource calls through").
286	+  /// `allowMalformed: true` mirrors every other decode step in this app
287	+  /// (RNF09: never throw on a malformed byte sequence) — a chunk that
288	+  /// can't be exactly transcoded still degrades to the replacement
289	+  /// character rather than crashing the stream.
290	+  ///
291	+  /// A connection that closes cleanly with no further error is simply a
292	+  /// stream that ends with no further `Right`/`Left` emitted — detecting
293	+  /// that as a "mid-stream drop" (no `done`/`error` SSE event ever seen)
294	+  /// is the caller's job, not this method's; `ApiClient` has no notion of
295	+  /// the SSE event grammar.
296	+  Stream<Either<Failure, String>> postStream(
297	+    String function, {
298	+    List<String> pathParams = const [],
299	+    Object? data,
300	+  }) async* {
301	+    try {
302	+      final response = await _dio.post<ResponseBody>(
303	+        _urlBuilder.build(function, pathParams),
304	+        data: data,
305	+        options: Options(responseType: ResponseType.stream),
306	+      );
307	+      final body = response.data;
308	+      if (body == null) {
309	+        yield left(
310	+          const Failure.malformedResponse(message: 'Empty stream body'),
311	+        );
312	+        return;
313	+      }
314	+      await for (final bytes in body.stream) {
315	+        yield right(utf8.decode(bytes, allowMalformed: true));
316	+      }
317	+    } on DioException catch (e) {
318	+      yield left(await _mapStreamDioException(e));
319	+    } catch (e) {
320	+      yield left(Failure.malformedResponse(message: e.toString()));
321	+    }
322	+  }
323	+
324	+  /// [postStream]'s own error-mapping step. A non-2xx response to a
325	+  /// `ResponseType.stream` request is never auto-decoded into a `Map` by
326	+  /// dio's default transformer (dio's own contract: "you must return the
327	+  /// responseBody when Options.responseType is stream") — [e.response]'s
328	+  /// `data` is still the raw, undrained [ResponseBody] at this point, so
329	+  /// [_mapDioException]'s own `data is Map` check always misses it and
330	+  /// would otherwise collapse every real backend error code on this one
331	+  /// streaming endpoint into [Failure.malformedResponse]. Draining and
332	+  /// decoding it here, once, keeps that same `{code, message}` mapping
333	+  /// (`error-taxonomy.md`) correct for the stream path too, without
334	+  /// changing [_mapDioException]/`dioErrorCodeOf` themselves — both are
335	+  /// shared with `RetryInterceptor`, which never sees a stream response at
336	+  /// all (it retries before dio's transformer runs), so widening their
337	+  /// `Map`-only contract isn't needed here. Any failure to drain/decode
338	+  /// (including a non-JSON body) falls back to [_mapDioException]'s own
339	+  /// generic mapping unchanged.
340	+  Future<Failure> _mapStreamDioException(DioException e) async {
341	+    final data = e.response?.data;
342	+    if (data is ResponseBody) {
343	+      try {
344	+        final bytes = await data.stream.expand((chunk) => chunk).toList();
345	+        final decoded = jsonDecode(utf8.decode(bytes, allowMalformed: true));
346	+        if (decoded is Map && decoded['code'] is String) {
347	+          final message = decoded['message'];
348	+          final failure = Failure.fromCode(
349	+            decoded['code'] as String,
350	+            (message is String ? message : null) ?? 'Unknown error',
351	+          );
352	+          if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
353	+            _sessionExpiryNotifier.notifyExpired();
354	+          }
355	+          return failure;
356	+        }
357	+      } catch (_) {
358	+        // Falls through to the generic mapping below — same "never throw"
359	+        // rationale every other decode step in this file already follows.
360	+      }
361	+    }
362	+    return _mapDioException(e);
363	+  }
