1954	/// One parsed SSE event from `chat.messages.send`'s streaming response
1955	/// (`openapi.yaml`: `message_created -> context -> token* -> done|error`,
1956	/// in this order). `context` is intentionally never modeled here — the
1957	/// Boundaries explicitly exclude "rendering the SSE `context` event's
1958	/// retrieval/citation data"; `ChatRemoteDataSource` receives and discards
1959	/// it before it would ever become one of these. `error` likewise never
1960	/// becomes a member of this type — it's a terminal failure, surfaced as
1961	/// `Left(Failure.fromCode(...))` by the same stream this event type flows
1962	/// through (`ChatRepository.sendMessage`'s own `Stream<Either<Failure,
1963	/// ChatStreamEvent>>`), never wrapped as a `Right` value.
1964	///
1965	/// A plain sealed class, not `freezed` (mirrors `core/resource.dart`'s own
1966	/// `Resource<T>` — AD-12's prose: "Chat's state is its own sealed class,
1967	/// never forced into `Resource<T>`" extends to this smaller stream-event
1968	/// type too, no union/copyWith machinery needed for 3 fixed, flat shapes).
1969	sealed class ChatStreamEvent {
1970	  const ChatStreamEvent();
1971	}
1972	
1973	/// Design Notes: "`message_created` carries the persisted user-message
1974	/// id" — the id the backend just assigned to the user's own just-sent
1975	/// message (not the AI response being generated). Unused by this story's
1976	/// own `ChatCubit` (no retry-by-id feature yet, Boundaries) — modeled now
1977	/// so Story 6.3's retry call has a value to key off without re-parsing the
1978	/// stream.
1979	class ChatMessageCreatedEvent extends ChatStreamEvent {
1980	  const ChatMessageCreatedEvent(this.userMessageId);
1981	
1982	  final String userMessageId;
1983	
1984	  @override
1985	  bool operator ==(Object other) =>
1986	      identical(this, other) ||
1987	      (other is ChatMessageCreatedEvent &&
1988	          other.userMessageId == userMessageId);
1989	
1990	  @override
1991	  int get hashCode => userMessageId.hashCode;
1992	
1993	  @override
1994	  String toString() => 'ChatMessageCreatedEvent(userMessageId: $userMessageId)';
1995	}
1996	
1997	/// One `token` event's `delta` — Design Notes: "this spec assumes `token`
1998	/// carries a `delta` text field". `ChatCubit` appends [delta] onto the
1999	/// streaming AI bubble's content on every emission.
2000	class ChatTokenEvent extends ChatStreamEvent {
2001	  const ChatTokenEvent(this.delta);
2002	
2003	  final String delta;
2004	
2005	  @override
2006	  bool operator ==(Object other) =>
2007	      identical(this, other) || (other is ChatTokenEvent && other.delta == delta);
2008	
2009	  @override
2010	  int get hashCode => delta.hashCode;
2011	
2012	  @override
2013	  String toString() => 'ChatTokenEvent(delta: $delta)';
2014	}
2015	
2016	/// The stream's own successful terminator — marks the AI bubble `complete`.
2017	class ChatDoneEvent extends ChatStreamEvent {
2018	  const ChatDoneEvent();
